//! Design tokens for the Swiftly Rust UI.
//!
//! The values live in [`tokens`], which is generated by `src/bin/gen_tokens.rs` from the design file
//! (`App/design/Swiftly Player.isd`) and the kit snapshot `data/system.json`. Never edit `tokens.rs` by hand;
//! run the generator (see `README.md`). The value types are defined here in [`types`].
//!
//! Layout sets: [`LayoutSet::Touch`] (phones, tablets), [`LayoutSet::Desktop`] (windows with a pointer) and
//! [`LayoutSet::Tv`] (remote, about 3 m). Values that do not differ by layout set are in `tokens::common` and
//! `tokens::colour`.

pub mod types;

#[rustfmt::skip]
pub mod tokens;

pub use types::{Colour, Curve, LayoutSet, Shadow, TextStyle};
